#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DependencyShape {
    Rust,
    Path,
    Nikaia,
}

pub fn dependency(name: &str, typed: bool, kind: &str, has_path: bool) -> Result<DependencyShape, nikaia_std::error::Thrown<Refused>> {
    if typed {
        if kind == "rust" { return Ok(DependencyShape::Rust); }
        return Err(nikaia_std::error::throwing(Refused::Because(format!("Dependency `{}` has `type = \"{}\"`, which isn't a kind of dependency Nikaia knows. The only one is `rust`, for a crate from crates.io.", name, kind)), &"dependency"));
    }
    if has_path { return Ok(DependencyShape::Path); }
    Ok(DependencyShape::Nikaia)
}

pub fn crate_name(key: &str) -> String {
    let mut name: String = String::from("");
    for c in key.chars() { if c == '-' { name.push('_'); } else { name.push(c); } }
    name
}

pub(crate) fn contains(words: &[String], word: &str) -> bool {
    for w in words.iter() { if w == word { return true; } }
    false
}

pub(crate) fn choices(words: &[String]) -> String {
    let mut out: String = String::from("");
    for w in words.iter() {
        if !out.is_empty() { out.push_str(", "); }
        out.push_str(w);
    }
    out
}

